import { advisorAgentName, advisorProfile } from "./advisor-executor.ts";
import {
  enabledOrdinaryRoles,
  hasRuntimeError,
  hasAdvisorError,
  validAdvisors,
  isAdvisorEnabled,
  isRoleDisabled,
  type RuntimeState,
} from "./runtime.ts";
import { ROLE_LABELS } from "./types.ts";
import type {
  AdvisorLaunch,
  EffectiveDelegateState,
  ModelConfigKey,
  ModelRef,
  ModelRole,
  Preference,
  ThinkingPolicy,
} from "./types.ts";

/**
 * The block is generated by decision flow, not by obligation type: what the policy is, when to work
 * directly, when to consult, which role, how to brief, how to launch, and what to do with results.
 * Every fragment below is rendered only for the axes and roles that are active, so an Advisor-only
 * session gains no execution guidance and a disabled role gains no rule.
 */
const PURPOSE =
  "This session's policy governs delegation, not permissions or your main model or thinking.";

const NORMAL_POLICY =
  "Delegate substantial, separable work only when the expected benefit clearly outweighs briefing, supervision, review, and integration cost. Count parallelism as a benefit only when valuable work can advance now or elapsed time matters. A merely possible fresh perspective is not enough by itself. Keep borderline work with the main agent.";
const AGGRESSIVE_POLICY =
  "Delegate substantial, separable, independently checkable work by default when the benefit is plausible even if not proven, including a useful independent perspective; give a clear objective and acceptance criteria. Keep poorly bounded or tightly coupled work, work dominated by integration or final accountability, and work with clearly prohibitive delegation overhead with the main agent.";
const TINY_EDIT = "A tiny edit already in context may stay here.";
const ORCHESTRATOR_POLICY =
  "Delegate all transferable execution before performing it whenever an enabled capable role and authorized launcher are available, regardless of size. This includes small lookups, code reading, detailed planning, implementation, tests, writing, detailed review, and integration mechanics. Perform only minimal bootstrap: mandatory instructions, tool discovery, and narrow assignment scope; do not pre-solve or broadly inspect the repository. Batch small tasks without forcing recursive fanout. After assigning a task, do not take it over or run an equivalent worker while it is pending; coordinate only disjoint work, use the host wait/completion mechanism, and consume its result before dependent work or finalizing. Retain strategy, objectives, critical user decisions, coordination, safety, evidence evaluation, final acceptance, and concise synthesis; final responsibility does not permit personally completing review or integration mechanics. Reinspect returned work only for a concrete gap, risk, or contradiction; delegate transferable fixes or rechecks. Direct execution is allowed only for genuinely non-transferable work, no enabled capable role, a confirmed unavailable authorized launcher, or an explicit user or higher-priority requirement. Before direct work, state the concrete exception briefly, do only the minimum, do not repeat it while unchanged, and resume delegation when it ends. Never use a final-review or integration label to do the whole task personally. Triviality, convenience, economics, transfer cost, size, or familiarity do not justify direct execution. Keep narration concise, but never omit requested detail, risks, evidence, or safety information. Do not promise savings.";

/** Normal and aggressive keep their own retention; orchestrator states it in its intensity rule. */
const LEGACY_OWNERSHIP =
  "Retain global strategy, coordination, integration, final review and acceptance, and context too costly or risky to transfer.";
const USER_RESTRICTIONS =
  "User restrictions on launches, consultation, or destructive operations still apply; advice never authorizes execution.";
const DELEGATION_RESTRICTIONS =
  "User restrictions on launches or destructive operations still apply; delegation never authorizes execution.";

/** The Visual Design gate is a forward reference, so it is emitted only when that role is configured. */
function roleFitPolicy(visualDesign: boolean): string {
  return `${visualDesign ? "Before choosing an ordinary role, check Visual Design below. Otherwise weigh" : "Weigh"} demand, ambiguity, dependencies, risk, quantity, and error/review cost together, and choose the least costly enabled role that meets the acceptance criteria and evidence; if none can, keep the work. A more capable enabled role may cover a disabled role's work on the same acceptance and evidence; never choose a less capable one because it is the only one enabled. Agent type does not determine the model role.`;
}

const SMALL_ROLE_POLICY =
  "Small: bounded searches, planned implementation, tests, documentation, focused review; retain unsettled approach decisions. Difficult but defined execution can use higher thinking. Yes: rename known call sites; no: reconcile competing designs. Batch repetitive independent work into Small; volume alone never warrants escalation.";
const MEDIUM_ROLE_POLICY =
  "Medium: planning, meaningful ambiguity, cross-module tracing and synthesis, comparisons, or difficult decisions. Small need not fail first. Yes: reconcile three stores; no: repeat eight headers.";
const LARGE_EXCEPTIONAL_POLICY =
  "Large: exceptional while Small and Medium are enabled: persistent failure, framework conflict, contradictory hypotheses, or reliable prior evidence that ordinary roles cannot answer trustworthily. Yes: diagnose contradictory failures; no: a routine plan. No ceremonial failures. Diagnose before patching; reevaluate fit after planning.";
const LARGE_COVERS_MEDIUM_POLICY =
  "With Medium disabled, Large covers planning, unresolved ambiguity, cross-module synthesis and stuck diagnosis Small cannot deliver; Small need not fail first. Yes: reconcile three stores or diagnose contradictory failures; no: eight identical headers. Select Large explicitly for capability, never a silent Medium fallback; retain critical and user decisions, diagnose before patching, return settled implementation to Small.";
const LARGE_CAPABLE_POLICY =
  "Large: planning, unresolved ambiguity, cross-module synthesis, stuck diagnosis, and defined execution a disabled role would take, only on the same acceptance and evidence; as the capable enabled candidate it is not limited to exceptional blockers. Diagnose before patching; reevaluate fit after planning.";

const VISUAL_DESIGN_POLICY =
  "Visual Design: when the delegated presentation is the primary acceptance criterion, behavior and data contracts are fixed, the surface is bounded, and no logic, APIs, routes, architecture, tooling, or cross-system work is needed, select it before ordinary roles. It may design, create, implement and review presentation and assets, including contrast and focus visibility, and must run and report the relevant existing checks. Use its exact model and thinking policy, never an ordinary role's model. Reevaluate each phase and split mixed work.";
const VISUAL_DESIGN_ROUTING_LEGACY =
  "Route interaction behavior, state, validation, semantic HTML, keyboard/ARIA, authentication, permissions, persistence, test infrastructure and behavior tests to an enabled ordinary role that fits, or keep them with the main agent. Eligibility alone never forces delegation.";
const VISUAL_DESIGN_ROUTING_ORCHESTRATOR =
  "Route interaction behavior, state, validation, semantic HTML, keyboard/ARIA, authentication, permissions, persistence, test infrastructure and behavior tests to a capable enabled ordinary role. Apply the all-transferable rule: you retain cross-domain integration responsibility and final acceptance, but delegate transferable integration mechanics and detailed review.";

const CHILD_BRIEF_POLICY = `Write each child's brief before launching it: bounded outcome and owner; decided context and invariants; scope, permissions and exclusions; verification and acceptance; return format and destination; stop and ask conditions. An unresolved decision stays a question the child may answer, never a settled invariant. Forbid edits during a review or search, implementation during a plan, and changes outside the scope. Tests establish named expected behaviors, not a coverage count. Apply this to host workers and reviewers: an agent name does not stand in for the model role or grant permission. A missing heading alone never blocks a launch; ask only when a material decision or authorization cannot be inferred from the session.`;

/** One short emphasis and example per role; only enabled roles are rendered. */
const BRIEF_ROLE_EMPHASIS: Record<ModelConfigKey, string> = {
  small: `defined execution. "Add SameSite=Lax in session.ts; keep expiry; return the patch and the attribute test; stop if expiry must change."`,
  medium: `the open question the child must resolve. "Compare the three stores and recommend one; return the trade-offs and the files each step touches; do not change the public API."`,
  large: `unconverged work: failure evidence, hypotheses tested, stop condition. "Diagnose the contradictory failures in both modules; return the cause and the smallest fix; stop before editing."`,
  uiDesign: `presentation only, never logic, state, ARIA or keyboard. "Restyle header spacing only; keep markup, copy and logic; return responsive evidence; stop if behavior must change."`,
  advisor: `advice only, never implementation or tool checks. "Keep sliding expiry? Return the risks and the indispensable missing facts; do not implement."`,
};

function childBriefPolicy(
  enabled: readonly ModelRole[],
  visualDesign: boolean,
  advisor: boolean,
): string {
  const keys: ModelConfigKey[] = [
    ...enabled,
    ...(visualDesign ? (["uiDesign"] as const) : []),
    ...(advisor ? (["advisor"] as const) : []),
  ];
  return [
    CHILD_BRIEF_POLICY,
    ...keys.map((key) => `- ${ROLE_LABELS[key]}: ${BRIEF_ROLE_EMPHASIS[key]}`),
  ].join("\n");
}

/**
 * How the advisor receives context. `fork` lets the host branch the whole session, the way Claude
 * Code's advisor sees the full transcript; `fresh` asks for a short self-contained brief instead.
 */
export type AdvisorContext = "fork" | "fresh";

// Fork only while the session fills at most half of the advisor's window, leaving room for its own
// prompt, its reasoning and tokenizer differences between models. Switching back needs a clear drop
// (for example after compaction) so the policy line does not flap and break provider prompt caching.
const FORK_MAX_SHARE = 0.5;
const FORK_RESUME_SHARE = 0.35;

export function selectAdvisorContext(
  previous: AdvisorContext | undefined,
  sessionTokens: number | null | undefined,
  advisorContextWindow: number | undefined,
): AdvisorContext {
  if (!advisorContextWindow || advisorContextWindow <= 0) return "fresh";
  // Pi reports null right after compaction or before the first response; keep the last mode then.
  if (typeof sessionTokens !== "number" || !Number.isFinite(sessionTokens) || sessionTokens < 0)
    return previous ?? "fork";
  const share = sessionTokens / advisorContextWindow;
  if (share > FORK_MAX_SHARE) return "fresh";
  if (share < FORK_RESUME_SHARE) return "fork";
  return previous ?? "fork";
}

const ADVISOR_CONTEXT_GUIDANCE: Record<AdvisorContext, string> = {
  fork: `Context: fork, the question alone (decision, options, uncertainty) sent with this conversation to each provider; retry once fresh with a self-contained brief only after a rejected oversized fork, never duplicating a running consultation.`,
  fresh: `Context: fresh, because the conversation is too large for the Advisor's window or its size is unknown; write a short self-contained brief with objective and constraints, relevant facts, options and proposal, and the uncertainty; separate facts from assumptions.`,
};

/**
 * The consultation contract is shared by both axes: the Advisor never implements or runs
 * tool-dependent checks, its model and profile are exact, thinking is supported and never an
 * ambient default, it launches in the background unless the host or user requires foreground,
 * and its answers are consumed before the decision that depends on them.
 */
function advisorPolicy(
  context: AdvisorContext,
  launch: AdvisorLaunch,
  count: number,
  providerProfile = false,
): string {
  return `Consulting is part of this policy, not delegated execution; the Advisor never implements or runs tool-dependent checks, and direct-work guidance does not rule it out. Consult after orientation, before the first edit or state-changing command, any interpretation, approach or assumption, a substantive analysis or recommendation, a recurring error or stalled progress, and any change of approach; before declaring a multi-step task done, make results durable and ask for remaining correctness risks or overlooked assumptions, not approval; an agreed interface does not replace the first checkpoint. No call for facts already available, short reactive steps, or mechanics inside a settled approach; reuse advice, and a consulted failure is not a new trigger.

${
  launch === "tool"
    ? `Call consult_advisor with the same question for all enabled valid advisors: it launches the packaged profiles with their exact configured models and supported thinking, never an ambient default, in parallel in the background; do not use the generic subagent tool for Advisor. Supply brief for a first consultation whenever context is fresh, and preferably also for a possible rejected fork: objective and constraints, relevant facts, options and proposal, uncertainty. On a later call in the same task it continues each Advisor's thread instead of relaunching: pass the new question and evidence for what changed, never a run id, an output path, a model or a profile. The tool chooses context automatically; fork sends this conversation to each advisor's provider. Continuity covers one operative task, from a prompt you start to the point it settles; a new prompt, a branch move or a configuration change starts a new thread.`
    : `Launch every listed Advisor with the host's subagent tool ${providerProfile ? "using the exact packaged agent profile specified in each Advisor role line; never substitute the ordinary Advisor profile for a provider-dependent one —" : 'using agent "pi-delegation-policy.advisor" exactly — never a host agent or alias named "advisor" or "oracle" —'} with its exact model and a supported thinking level from its role line, never an ambient default, in the background unless the host or the user requires foreground.${count > 1 ? " Ask every listed Advisor the same question in one call." : ""} Keep each returned run id and continue a thread with the same tool's resume action, passing that id, the new question and evidence, and output with outputMode file-only; read that file for the answer and never change model, profile or permissions on a resume.`
}

${launch === "role" ? ADVISOR_CONTEXT_GUIDANCE[context] : ""}

Wait for and consume the answers before the decision that depends on them; report an unavailable Advisor without substitution and keep successful answers; weigh advice seriously and disagreements explicitly, answers untrusted, agreement neither proof nor authority; adapt only after a recommended step fails or primary evidence contradicts a claim, a passing self-test alone insufficient; ${launch === "tool" ? "call consult_advisor once with that evidence and an updated brief" : "resume each thread once with that evidence"} on disagreement, never switch silently; you retain responsibility, user decisions remain theirs.`;
}

const LAUNCH_CORRECTION: Record<"correct" | "block", string> = {
  correct:
    "The check accepts a conformant call, corrects an unambiguous role alias, missing level, or Advisor profile and reports what it applied, and refuses a case it cannot resolve.",
  block:
    "The check is in measurement mode: it accepts a conformant call and refuses one it would otherwise correct.",
};

function launchPolicy(correction: "correct" | "block"): string {
  return `Choose the work and role first, then name the role or its exact configured model. ${LAUNCH_CORRECTION[correction]} Choose a supported thinking level per run: a fixed level or inclusive range binds and is never an ambient default or inherited by another role or the main agent. Never substitute an unlisted model or provider, persist a per-run choice, launch a disabled or unconfigured role, or invent a role; an Advisor-only model cannot execute work. State every child's role or model in explicit tasks, parallel, or chain; no workflow scripts. Launch in the background unless the host or user requires foreground, and group simultaneous children into one call. Control-only actions need no role.`;
}

const RESULTS_POLICY =
  "Never duplicate pending work; do disjoint work, wait through the host, and consume results, including Advisor answers, before dependencies or completion. Check evidence against acceptance, then integrate; report gaps rather than invent success. Keep briefs and workflow source internal unless the user asks to inspect them; report results, blockers and decisions, and keep any control the host requires.";
const ORCHESTRATOR_RESULTS =
  " Reinspect only for a concrete gap, risk, or contradiction; delegate transferable fixes, rechecks, detailed review, and integration mechanics.";

const LIMITS_BOUNDARY: Record<"correct" | "block", string> = {
  correct:
    "The extension corrects or refuses launches, not delegation decisions; it never routes, supervises, or accepts results.",
  block:
    "The extension refuses launches, not delegation decisions; it never routes, supervises, or accepts results.",
};
const LIMITS_REFUSAL =
  "It refuses a call whose model, level, or Advisor profile it cannot settle, and a workflow script whose models it cannot see; the refusal lists the accepted launches.";
const LIMITS_RETENTION =
  "Consultation costs latency, tokens, and normal executor/provider retention. Only the first turn of a thread carries the verified launch contract; later turns rely on the host's inherited contract plus the agent, model and thinking it reports, and any mismatch blocks the thread instead of retrying it.";

function limitsTools(advisorTool: boolean): string {
  return advisorTool
    ? "Only explicit tools reach the authorized host executor, never a hook: context_shunt_delegate asks one bounded question about an already-preserved text artifact, and consult_advisor consults the configured advisors; neither replaces delegation, the launcher, or the roles above."
    : "Only explicit tools reach the authorized host executor, never a hook or in place of delegation: context_shunt_delegate asks one bounded question about an already-preserved text artifact.";
}

/** The Advisor-only branch must not deny the launch `consult_advisor` performs in tool mode. */
function advisorOnlyLimits(advisorTool: boolean): string {
  return advisorTool
    ? "Only an explicit consult_advisor call requests an Advisor launch through the authorized host executor, never a hook; the extension does not supervise the answers or accept them for you."
    : "The extension does not launch or supervise Advisor; the main agent uses an authorized host launcher and remains responsible for the decision.";
}

function hasSmallMedium(enabled: readonly ModelRole[]): boolean {
  return enabled.includes("small") && enabled.includes("medium");
}

function preferenceGuidance(preference: Preference, enabled: readonly ModelRole[]): string {
  if (!hasSmallMedium(enabled)) {
    return `${preference} is inactive because Small or Medium is disabled.`;
  }
  if (preference === "efficient") {
    return "Use efficient only as a Small tie-break when Small and Medium are comparably credible. Do not choose Small when Medium is a materially better task fit.";
  }
  if (preference === "intensive") {
    return "Use intensive only as a Medium tie-break when Small and Medium are comparably credible. Do not choose Medium when Small is the clearly better task fit.";
  }
  return "Standard adds no Small or Medium bias; follow task fit.";
}

function preferencePreview(preference: Preference, enabled: readonly ModelRole[]): string {
  if (!hasSmallMedium(enabled)) return `${preference} inactive (Small or Medium disabled)`;
  if (preference === "efficient") return "efficient breaks comparable fits toward Small";
  if (preference === "intensive") return "intensive breaks comparable fits toward Medium";
  return "standard has no extra bias";
}

function promptString(value: string): string {
  return JSON.stringify(value)
    .replaceAll("<", "\\u003c")
    .replaceAll(">", "\\u003e")
    .replaceAll("&", "\\u0026");
}

function formatLaunchModel(reference: ModelRef): string {
  return promptString(`${reference.provider}/${reference.model}`);
}

type RoleThinking =
  | { kind: "fixed"; level: string }
  | { kind: "range"; min: string; max: string }
  | { kind: "unset" };

function roleThinking(policy: ThinkingPolicy | undefined): RoleThinking {
  if (!policy) return { kind: "unset" };
  return "level" in policy
    ? { kind: "fixed", level: policy.level }
    : { kind: "range", min: policy.min, max: policy.max };
}

/** Fixed policies show the literal level; range and unset keep the `:LEVEL` placeholder. */
function formatThinkingLaunchModel(reference: ModelRef, thinking: RoleThinking): string {
  const base = `${reference.provider}/${reference.model}`;
  return promptString(thinking.kind === "fixed" ? `${base}:${thinking.level}` : `${base}:LEVEL`);
}

function thinkingPolicyText(thinking: RoleThinking): string {
  if (thinking.kind === "fixed") return `fixed ${thinking.level} (must not change)`;
  if (thinking.kind === "range")
    return `range ${thinking.min}..${thinking.max} inclusive (choose within it)`;
  return "unset (choose per run)";
}

function thinkingPreviewToken(thinking: RoleThinking): string {
  if (thinking.kind === "fixed") return `:${thinking.level}`;
  if (thinking.kind === "range") return `:${thinking.min}..${thinking.max}`;
  return ":per-run";
}

function roleName(role: ModelRole): string {
  return role[0]!.toUpperCase() + role.slice(1);
}

/** One mechanical line per enabled role: the base a launch carries and the level it may carry. */
function roleLine(label: string, reference: ModelRef, thinking: RoleThinking, detail = ""): string {
  return `- ${label}: exact model base: ${formatLaunchModel(reference)}; pi-subagents form: ${formatThinkingLaunchModel(reference, thinking)}; thinking: ${thinkingPolicyText(thinking)}${detail}.`;
}

function rolesByState(effective: EffectiveDelegateState): {
  enabled: ModelRole[];
  disabled: ModelRole[];
  unconfigured: ModelRole[];
} {
  return {
    enabled: enabledOrdinaryRoles(effective),
    disabled: (["small", "medium", "large"] as const).filter((role) =>
      isRoleDisabled(effective[role]),
    ),
    unconfigured: (["small", "medium", "large"] as const).filter(
      (role) => effective[role] === undefined,
    ),
  };
}

export function buildPolicyPreview(
  effective: EffectiveDelegateState,
  validAdvisorCount?: number,
): string[] {
  if (effective.intensity === "off") {
    if (!isAdvisorEnabled(effective)) return ["off · no policy injected"];
    return [
      "Delegation off · Advisor on · consultation only",
      validAdvisorCount === undefined
        ? `${effective.advisors.length} Advisor models configured · validation pending`
        : `${validAdvisorCount} of ${effective.advisors.length} advisors valid${validAdvisorCount === 0 ? " · no policy can be injected" : ""}`,
    ];
  }

  const { enabled, disabled, unconfigured } = rolesByState(effective);
  if (unconfigured.length > 0) {
    return [`active · ${roleName(unconfigured[0]!)} not configured · no policy can be injected`];
  }
  if (enabled.length === 0)
    return ["active · no ordinary role enabled · no policy can be injected"];

  const references = enabled
    .map(
      (role) =>
        `${roleName(role)} ${formatLaunchModel(effective[role] as ModelRef)}${thinkingPreviewToken(roleThinking(effective.thinking[role]))}`,
    )
    .join(" · ");
  return [
    `${effective.intensity} · task fit first · ${preferencePreview(effective.preference, enabled)}`,
    `Enabled: ${enabled.map(roleName).join(", ")}${disabled.length ? ` · Disabled: ${disabled.map(roleName).join(", ")}` : ""}`,
    `${references} · exact model plus per-task thinking required only for roles with no policy; neither uses an ambient default.`,
    ...(effective.intensity === "orchestrator"
      ? ["Delegate all transferable work; main agent keeps final acceptance."]
      : []),
  ];
}

/** Shared with role-mode tool redirection so launch models and thinking stay identical. */
export function advisorRoleLines(state: RuntimeState): string {
  const { effective } = state;
  return validAdvisors(state)
    .map(({ index, setting }) => {
      // Advisor thinking is never configured, so the main agent always chooses it per run.
      const thinking: RoleThinking = { kind: "unset" };
      const label =
        effective.advisors.length === 1 ? "Advisor (optional)" : `Advisor ${index + 1} (optional)`;
      const profile = advisorProfile(setting, state.admissions);
      const extension =
        profile === "anthropic-auth"
          ? "; provider extension explicitly enabled: normal configuration, startup hook and account diagnostic command are trusted host code, not model tools; never invoke the diagnostic automatically"
          : profile === "admitted"
            ? "; provider extension admitted by the user: it runs as trusted host code in the child, not as model tools"
            : "";
      return `\n${roleLine(label, setting, thinking, `; agent profile: ${promptString(advisorAgentName(setting, state.admissions))}${extension}`)}`;
    })
    .join("");
}

/** The role rules are generated only for the enabled subset; a disabled role never gains a rule. */
function roleRules(enabled: readonly ModelRole[], visualDesign: boolean): string {
  const rules = [roleFitPolicy(visualDesign)];
  if (enabled.includes("small")) rules.push(SMALL_ROLE_POLICY);
  if (enabled.includes("medium")) rules.push(MEDIUM_ROLE_POLICY);
  if (enabled.includes("large")) {
    rules.push(
      enabled.includes("small") && enabled.includes("medium")
        ? LARGE_EXCEPTIONAL_POLICY
        : enabled.includes("small")
          ? LARGE_COVERS_MEDIUM_POLICY
          : LARGE_CAPABLE_POLICY,
    );
  }
  return rules.join("\n");
}

export function buildDelegationPolicy(
  state: RuntimeState,
  advisorContext: AdvisorContext = "fresh",
): string | undefined {
  const { effective } = state;
  const advisorEnabled = isAdvisorEnabled(effective) && !hasAdvisorError(state);
  const advisors = advisorEnabled ? validAdvisors(state) : [];
  const advisorRoleLine = advisorEnabled ? advisorRoleLines(state) : "";
  const advisorSection = advisorEnabled
    ? `\n\nAdvisor consultation:\n${advisorPolicy(
        advisorContext,
        effective.advisorLaunch,
        advisors.length,
        advisors.some(({ setting }) => advisorProfile(setting, state.admissions) !== undefined),
      )}`
    : "";
  const advisorTool = effective.advisorLaunch === "tool" && advisorEnabled;
  const correction = state.launchCorrection ?? "correct";

  if (effective.intensity === "off" || hasRuntimeError(state)) {
    if (!advisorRoleLine) return undefined;
    return `<delegation_policy>
<!-- pi-delegation-policy:owned -->
Purpose
Delegation intensity: ${effective.intensity}${hasRuntimeError(state) ? " (unavailable)" : ""}. Advisor: on. Only consultation guidance is active: this policy requests no execution delegation, ordinary or Visual Design role selection, or ContextShunt. Keep execution with the main agent unless other applicable instructions require otherwise. Host permissions and user restrictions still apply.${advisorSection}

Roles:${advisorRoleLine}

Limits:
${advisorOnlyLimits(advisorTool)} ${LIMITS_RETENTION}
</delegation_policy>`;
  }
  const { enabled, disabled } = rolesByState(effective);
  if (enabled.length === 0) return undefined;

  const intensityPolicy =
    effective.intensity === "normal"
      ? NORMAL_POLICY
      : effective.intensity === "aggressive"
        ? AGGRESSIVE_POLICY
        : ORCHESTRATOR_POLICY;
  const orchestrator = effective.intensity === "orchestrator";
  const ownership = orchestrator ? "" : ` ${LEGACY_OWNERSHIP}`;
  const restrictions = advisorEnabled ? USER_RESTRICTIONS : DELEGATION_RESTRICTIONS;
  const visualDesign = effective.uiDesign
    ? `\n\n${VISUAL_DESIGN_POLICY} ${orchestrator ? VISUAL_DESIGN_ROUTING_ORCHESTRATOR : VISUAL_DESIGN_ROUTING_LEGACY}`
    : "";
  const visualDesignLine = effective.uiDesign
    ? `\n${roleLine("Visual Design", effective.uiDesign, roleThinking(effective.thinking.uiDesign))}`
    : "";
  const roleLines = enabled
    .map((role) =>
      roleLine(roleName(role), effective[role] as ModelRef, roleThinking(effective.thinking[role])),
    )
    .join("\n");
  const enabledLine = `Enabled ordinary roles: ${enabled.map(roleName).join(", ")}.${disabled.length ? ` Disabled ordinary roles: ${disabled.map(roleName).join(", ")}.` : ""}`;

  return `<delegation_policy>
<!-- pi-delegation-policy:owned -->
Purpose
${PURPOSE}

Do it yourself?
Intensity: ${effective.intensity}. ${intensityPolicy}${orchestrator ? "" : ` ${TINY_EDIT}`}${ownership} ${restrictions}${advisorSection}

Role selection:
${roleRules(enabled, Boolean(effective.uiDesign))}
Model preference: ${effective.preference}. ${preferenceGuidance(effective.preference, enabled)}${visualDesign}

Child briefs:
${childBriefPolicy(enabled, Boolean(effective.uiDesign), advisorEnabled)}

Launch:
${launchPolicy(correction)}

Roles:
${enabledLine}
${roleLines}${visualDesignLine}${advisorRoleLine}

Results:
${RESULTS_POLICY}${orchestrator ? ORCHESTRATOR_RESULTS : ""}

Limits:
${LIMITS_BOUNDARY[correction]} ${LIMITS_REFUSAL} ${limitsTools(advisorTool)} ${LIMITS_RETENTION}
</delegation_policy>`;
}
